	// without restarting their pods.
	// +optional
	// +kubebuilder:validation:XValidation:rule="!('temporal.io/build-id' in self) && !('temporal.io/deployment-name' in self)",message="temporal.io/build-id and temporal.io/deployment-name are managed by the controller"
	DeploymentLabels map[string]string `json:"deploymentLabels,omitempty"`

	// How to rollout new workflow executions to the target version.
	RolloutStrategy RolloutStrategy `json:"rollout"`

	// How to manage sunsetting drained versions.
	SunsetStrategy SunsetStrategy `json:"sunset"`

	// WorkerOptions configures the worker's connection to Temporal.
	WorkerOptions WorkerOptions `json:"workerOptions"`
}

// DeploymentSpec returns the appsv1.DeploymentSpec struct constructed by
// examining the WorkerDeploymentSpec. If WorkerDeploymentSpec.deployment is
// non-nil, we return that. Otherwise, we construct an appsv1.DeploymentSpec
// with the older, deprecated Replicas, Template, MinReadySeconds and
// ProgressDeadlineSeconds fields.
func (s WorkerDeploymentSpec) DeploymentSpec() appsv1.DeploymentSpec {
	depSpec := appsv1.DeploymentSpec{}
	if s.Deployment != nil {
		ds := s.Deployment.DeepCopy()
		depSpec = *ds
	} else {
		if s.Template != nil {
			depSpec.Template = *s.Template
		}
		depSpec.Replicas = s.Replicas
		depSpec.MinReadySeconds = s.MinReadySeconds
		depSpec.ProgressDeadlineSeconds = s.ProgressDeadlineSeconds
	}
	if depSpec.Strategy.Type == "" {
		depSpec.Strategy = DefaultDeploymentStrategy()
	}
	return depSpec
}

// DrainingReplicas returns the replica count the controller keeps draining
// versions at. ok is false when DrainingDeployment.Replicas is unset or when
// the controller does not manage replicas because an autoscaler owns them.
func (s WorkerDeploymentSpec) DrainingReplicas() (replicas int32, ok bool) {
	if s.DrainingDeployment == nil || s.DrainingDeployment.Replicas == nil {
		return 0, false
	}
	if s.DeploymentSpec().Replicas == nil {
		return 0, false
	}
	return *s.DrainingDeployment.Replicas, true
}

// DrainingDeploymentSpec overrides settings on the Kubernetes Deployments of
// draining versions.
type DrainingDeploymentSpec struct {
	// Replicas is the number of pods for each draining version's Deployment.
	// A draining version only serves its pinned executions, so it often needs
	// fewer pods than the current version.
	//
	// Applies only when the controller manages replicas (deployment.replicas
	// is set). When unset, the controller leaves draining versions at their
	// current count.
	// +optional
	// +kubebuilder:validation:Minimum=1
	Replicas *int32 `json:"replicas,omitempty"`
}

// DefaultDeploymentStrategy returns the default appsv1.DeploymentStrategy
// using RollingUpdate deployment strategy type and the default values for
// MaxUnavailable and MaxSurge.
func DefaultDeploymentStrategy() appsv1.DeploymentStrategy {
	defaultMaxUnavailable := intstr.FromString(defaults.DeploymentMaxUnavailable)
	defaultMaxSurge := intstr.FromString(defaults.DeploymentMaxSurge)
	return appsv1.DeploymentStrategy{
		Type: appsv1.RollingUpdateDeploymentStrategyType,
		RollingUpdate: &appsv1.RollingUpdateDeployment{
			MaxUnavailable: &defaultMaxUnavailable,
			MaxSurge:       &defaultMaxSurge,
		},
	}

}

// Condition reason constants for WorkerDeployment.
//
// These strings appear in status.conditions[].reason and are part of the CRD's
// status API. Operators, monitoring rules, and scripts may depend on them.
// They should be treated as stable within an API version and renamed only with
// a corresponding version bump.
const (
	// ReasonRolloutComplete is set on ConditionReady=True and ConditionProgressing=False
	// when the target version has been successfully registered as the current version.
	ReasonRolloutComplete = "RolloutComplete"

	// ReasonReconcileSucceeded is set on ConditionStalled=False after any reconcile
	// that completed without a blocking error, whatever stage the rollout is at.
	// It is what allows a WorkerDeployment that recovers from a blocking error to
	// stop reporting Failed to kstatus consumers.
	ReasonReconcileSucceeded = "ReconcileSucceeded"

	// ReasonWaitingForPollers is set on ConditionProgressing=True when workers are
	// not yet (or are no longer) actively polling Temporal. This covers both:
	// (1) the target version's Kubernetes Deployment has been created but the
	// version is not yet registered with Temporal, and (2) the target version has
	// become current but one or more of its task queues have no active poller.
	ReasonWaitingForPollers = "WaitingForPollers"

	// ReasonWaitingForPromotion is set on ConditionProgressing=True when the target
	// version is registered with Temporal (Inactive) but has not yet been promoted
	// to current or ramping.
	ReasonWaitingForPromotion = "WaitingForPromotion"

	// ReasonRamping is set on ConditionProgressing=True when the target version is
	// the ramping version and is receiving a configured percentage of new workflows.
	ReasonRamping = "Ramping"

	// ReasonConnectionNotFound is set on ConditionProgressing=False when the
	// referenced Connection resource cannot be found.
	ReasonConnectionNotFound = "ConnectionNotFound"

	// ReasonClusterConnectionUnsupported is set on ConditionProgressing=False when a
	// WorkerDeployment references a ClusterConnection but the controller is namespace-scoped.
	// ClusterConnection is cluster-scoped, so such a controller can never read it.
	ReasonClusterConnectionUnsupported = "ClusterConnectionUnsupported"

	// ReasonAuthSecretInvalid is set on ConditionProgressing=False when the credential
	// secret referenced by the Connection is misconfigured. This covers:
	// (1) the secret reference has an empty name, (2) the named Kubernetes Secret
	// cannot be fetched or has an unexpected type, and (3) the mTLS certificate in
	// the secret is expired or about to expire.
	ReasonAuthSecretInvalid = "AuthSecretInvalid"

	// ReasonTemporalClientCreationFailed is set on ConditionProgressing=False when the
	// Temporal SDK client cannot connect to the server (dial failure or failed health
	// check). The credentials were valid; the server itself is unreachable.
	ReasonTemporalClientCreationFailed = "TemporalClientCreationFailed"

	// ReasonTemporalStateFetchFailed is set on ConditionProgressing=False when the
	// controller cannot query the current worker deployment state from Temporal.
	ReasonTemporalStateFetchFailed = "TemporalStateFetchFailed"

	// ReasonInvalidSpec is set on ConditionReady=False and ConditionProgressing=False
	// when the spec fails validation that the CRD schema cannot enforce (e.g. rampPercentage
	// ordering, gate input/inputFrom exclusivity). Reconciliation resumes automatically
	// when the user corrects the spec and applies it.
	ReasonInvalidSpec = "InvalidSpec"

	// Deprecated: Use ReasonRolloutComplete on ConditionReady instead.
	ReasonConnectionHealthy = "ConnectionHealthy"

	// ReasonActivePollers is set on ConditionProgressing=False when the target
	// version has become current and all known task queues have at least one
	// active poller. This mirrors ReasonWaitingForPollers on
	// ConditionProgressing=True: it reports only that workers are actively
	// polling the server, not that the pollers themselves are otherwise healthy.
	// Also used as the reason on the Normal Event emitted when a version
	// transitions from having no active pollers (or unknown status) back to
	// actively polling every known task queue.
	ReasonActivePollers = "ActivePollers"

	// ReasonPollerStatusUnknown is set on ConditionProgressing=False when poller
	// status could not be determined for the current version (e.g. a transient
	// DescribeTaskQueue error). This must NOT be treated as "no pollers" -- it
	// means "don't know", not "broken".
	ReasonPollerStatusUnknown = "PollerStatusUnknown"
)

// VersionStatus indicates the status of a version.
// +enum
type VersionStatus string

const (
	// VersionStatusNotRegistered indicates that the version is not registered
	// with Temporal for any worker deployment. It may be not yet created, or
	// may have been deleted.
	VersionStatusNotRegistered VersionStatus = "NotRegistered"

	// VersionStatusCreated indicates that the version has been created explicitly.
	// When the first poll requests for this version come in, the version status
	// will change to Inactive.
	VersionStatusCreated VersionStatus = "Created"

	// VersionStatusInactive indicates that the version is registered in a Temporal
	// worker deployment, but has not been set to current or ramping.
	// A version is registered in a worker deployment after a poller with appropriate
	// DeploymentOptions starts polling.
	VersionStatusInactive VersionStatus = "Inactive"

	// VersionStatusRamping indicates that the version is the ramping version of its
	// worker deployment. It is accepting some percentage of new workflow executions.
	VersionStatusRamping VersionStatus = "Ramping"

	// VersionStatusCurrent indicates that the version is the current version of its
	// worker deployment. It is accepting all new workflow executions except for the
	// percent that are sent to the ramping version, if one exists.
	VersionStatusCurrent VersionStatus = "Current"

	// VersionStatusDraining indicates that the version has stopped accepting new workflows
	// (is no longer ramping or current) and DOES have open workflows pinned to it.
	VersionStatusDraining VersionStatus = "Draining"

	// VersionStatusDrained indicates that the version has stopped accepting new workflows
	// (is no longer ramping or current) and does NOT have open workflows pinned to it.
	// This version MAY still receive query tasks associated with closed workflows.
	VersionStatusDrained VersionStatus = "Drained"
)

