type DefaultVersionUpdateStrategy string

const (
	// UpdateManual scales worker resources up or down, but does not update the current or ramping worker deployment version.
	UpdateManual DefaultVersionUpdateStrategy = "Manual"

	// UpdateAllAtOnce starts 100% of new workflow executions on the new worker deployment version as soon as it's healthy.
	UpdateAllAtOnce DefaultVersionUpdateStrategy = "AllAtOnce"

	// UpdateProgressive ramps up the percentage of new workflow executions targeting the new worker deployment version over time.
	//
	// Note: If the Current Version of a Worker Deployment is nil and the controller cannot confirm that all Task Queues
	// in the Target Version have at least one unversioned poller, the controller will immediately set the new worker
	// deployment version to be Current and ignore the Progressive rollout steps.
	// Sending a percentage of traffic to a "nil" version means that traffic will be sent to unversioned workers. If
	// there are no unversioned workers, those tasks will get stuck. This behavior ensures that all traffic on the task
	// queues in this worker deployment can be handled by an active poller.
	UpdateProgressive DefaultVersionUpdateStrategy = "Progressive"
)

// PayloadMetadataEncodingType is the payload encoding the controller sets in the
// "encoding" metadata key when starting a gate workflow. These values mirror the MetadataEncoding* constants in
// go.temporal.io/sdk/converter/metadata.go.
// The SDK's "binary/null" is deliberately omitted: it declares an empty payload, so it
// would either be inert (no gate input to begin with) or discard an input the user went
// to the trouble of configuring. Omit the input instead.
// +enum
// +kubebuilder:validation:Enum=binary/plain;json/plain;json/protobuf;binary/protobuf
type PayloadMetadataEncodingType string

const (
	// PayloadMetadataEncodingTypeBinary is "binary/plain", for raw bytes passed
	// through unmodified. Requires a byte-valued input source: a ConfigMap
	// binaryData key or a Secret.
	PayloadMetadataEncodingTypeBinary PayloadMetadataEncodingType = "binary/plain"

	// PayloadMetadataEncodingTypeJSON is "json/plain", for a plain JSON message.
	// This is the encoding the controller produces when Encoding is unset.
	PayloadMetadataEncodingTypeJSON PayloadMetadataEncodingType = "json/plain"

	// PayloadMetadataEncodingTypeProtoJSON is "json/protobuf", for a protobuf
	// message serialized as JSON.
	PayloadMetadataEncodingTypeProtoJSON PayloadMetadataEncodingType = "json/protobuf"

	// PayloadMetadataEncodingTypeProto is "binary/protobuf", for a protobuf message
	// in binary wire format. Requires a byte-valued input source: inline Input is
	// JSON and cannot carry wire-format bytes.
	PayloadMetadataEncodingTypeProto PayloadMetadataEncodingType = "binary/protobuf"
)

type GateWorkflowConfig struct {
	WorkflowType string `json:"workflowType"`
	// Input is an arbitrary JSON object passed as the first parameter to the gate workflow.
	// For inputs with secrets use SecretKeyRef in InputFrom to omit from logs.
	// +optional
	Input *apiextensionsv1.JSON `json:"input,omitempty"`
	// InputFrom references a key in a ConfigMap or Secret whose contents are passed
	// as the first parameter to the gate workflow. The referenced value should be a JSON document.
	// For inputs with secrets use SecretKeyRef to omit from logs.
	// +optional
	InputFrom *GateInputSource `json:"inputFrom,omitempty"`
	// Encoding is the encoding type of the gate input. If unset, then the controller will use json/plain encoding.
	// The binary encoding types require a byte-valued input source instead of inline input.
	// +optional
	Encoding PayloadMetadataEncodingType `json:"encoding,omitempty"`
	// MessageType is the fully-qualified protobuf message name of the gate input, for example
	// "my.package.DeployRequest". Workers resolve the message type from the gate workflow's own
	// signature, so this is recorded for tools that only see the payload, such as the Temporal UI.
	// Required when Encoding is binary/protobuf, optional for json/protobuf, rejected otherwise.
	// +optional
	MessageType string `json:"messageType,omitempty"`
}

// GateInputSource references a value from a ConfigMap or a Secret
type GateInputSource struct {
	// Select a key of a ConfigMap in the same namespace
	// +optional
	ConfigMapKeyRef *corev1.ConfigMapKeySelector `json:"configMapKeyRef,omitempty"`
	// Select a key of a Secret in the same namespace
	// +optional
	SecretKeyRef *corev1.SecretKeySelector `json:"secretKeyRef,omitempty"`
}

// RolloutStrategy defines the strategy Temporal Worker Controller uses to
// promote the Temporal WorkerDeployment's target version (build ID).
//
// This struct does *not* influence the shape of the Kubernetes Deployment that
// is created by Temporal Worker Controller for an individual
// WorkerDeploymentVersion (build ID). Use WorkerDeploymentSpec.deployment to
// control the shape of the Kubernetes Deployment associated with a
// WorkerDeploymentVersion.
//
// +kubebuilder:validation:XValidation:rule="self.strategy != 'Progressive' || (has(self.steps) && size(self.steps) > 0)",message="steps are required for Progressive rollout"
// +kubebuilder:validation:XValidation:rule="!has(self.gate) || !has(self.gate.inputFrom) || (has(self.gate.inputFrom.configMapKeyRef) != has(self.gate.inputFrom.secretKeyRef))",message="exactly one of configMapKeyRef or secretKeyRef must be set"
// +kubebuilder:validation:XValidation:rule="!has(self.gate) || !has(self.gate.encoding) || self.gate.encoding != 'binary/protobuf' || has(self.gate.messageType)",message="gate.messageType is required when gate.encoding is binary/protobuf"
// +kubebuilder:validation:XValidation:rule="!has(self.gate) || !has(self.gate.messageType) || (has(self.gate.encoding) && (self.gate.encoding == 'json/protobuf' || self.gate.encoding == 'binary/protobuf'))",message="gate.messageType may only be set when gate.encoding is json/protobuf or binary/protobuf"
type RolloutStrategy struct {
	// Specifies how to treat concurrent executions of a Job.
	// Valid values are:
	// - "Manual"
	// - "AllAtOnce"
	// - "Progressive"
	Strategy DefaultVersionUpdateStrategy `json:"strategy"`

	// Gate specifies a workflow type that must run once to completion on the new worker deployment version before
	// any traffic is directed to the new version.
	Gate *GateWorkflowConfig `json:"gate,omitempty"`

	// Steps to execute progressive rollouts. Only required when strategy is "Progressive".
	// +optional
	// +kubebuilder:validation:MaxItems=20
	Steps []RolloutStep `json:"steps,omitempty" protobuf:"bytes,3,rep,name=steps"`
}

// SunsetStrategy defines strategy to apply when sunsetting k8s deployments of drained versions.
type SunsetStrategy struct {
	// ScaledownDelay specifies how long to wait after a version is drained before scaling its Deployment to zero.
	// Defaults to 1 hour.
	// +optional
	// +kubebuilder:default="1h"
	ScaledownDelay *metav1.Duration `json:"scaledownDelay"`

	// DeleteDelay specifies how long to wait after a version is drained before deleting its Deployment.
	// Defaults to 24 hours.
	// +optional
	// +kubebuilder:default="24h"
	DeleteDelay *metav1.Duration `json:"deleteDelay"`
}

type AllAtOnceRolloutStrategy struct{}

// +kubebuilder:validation:XValidation:rule="duration(self.pauseDuration) >= duration('30s')",message="pause duration must be at least 30s"
type RolloutStep struct {
	// RampPercentage indicates what percentage of new workflow executions should be
	// routed to the new worker deployment version while this step is active.
	// For example, 15 means 15%.
	//
	// Acceptable range is [1,99] (1% to 99%).
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=99
	RampPercentage int `json:"rampPercentage"`

	// PauseDuration indicates how long to pause before progressing to the next step.
	PauseDuration metav1.Duration `json:"pauseDuration"`
}

type ManualRolloutStrategy struct{}

