		Build()

	r := &WorkerDeploymentReconciler{Client: fakeClient, Scheme: scheme}
	err := r.migrateFromDeprecatedTWD(context.Background(), logr.Discard(), wd)
	require.NoError(t, err)
}

func TestMigrateFromDeprecatedTWD_UnrelatedDeploymentUntouched(t *testing.T) {
	// A Deployment owned by a different object must not be patched.
	const namespace = "default"
	twdUID := types.UID("deprecated-twd-uid")
	otherUID := types.UID("some-other-uid")

	twd := makeTWDStub("my-worker", namespace, nil)
	twd.UID = twdUID
	wd := makeWD("my-worker", namespace, "my-conn")

	unrelated := &appsv1.Deployment{
		ObjectMeta: metav1.ObjectMeta{
			Name:      "unrelated-deploy",
			Namespace: namespace,
			OwnerReferences: []metav1.OwnerReference{{
				APIVersion: "apps/v1",
				Kind:       "ReplicaSet",
				Name:       "rs-1",
				UID:        otherUID,
				Controller: ptr(true),
			}},
		},
		Spec: appsv1.DeploymentSpec{
			Selector: &metav1.LabelSelector{MatchLabels: map[string]string{"app": "other"}},
			Template: corev1.PodTemplateSpec{
				ObjectMeta: metav1.ObjectMeta{Labels: map[string]string{"app": "other"}},
				Spec: corev1.PodSpec{
					Containers: []corev1.Container{{Name: "app", Image: "app:v1"}},
				},
			},
		},
	}

	scheme := newTestScheme()
	fakeClient := fake.NewClientBuilder().
		WithScheme(scheme).
		WithObjects(twd, wd, unrelated).
		Build()

	r := &WorkerDeploymentReconciler{Client: fakeClient, Scheme: scheme}
	err := r.migrateFromDeprecatedTWD(context.Background(), logr.Discard(), wd)
	require.NoError(t, err)

	// Unrelated Deployment ownerRef must be unchanged.
	var gotDep appsv1.Deployment
	require.NoError(t, fakeClient.Get(context.Background(), types.NamespacedName{Name: "unrelated-deploy", Namespace: namespace}, &gotDep))
	require.Len(t, gotDep.OwnerReferences, 1)
	assert.Equal(t, otherUID, gotDep.OwnerReferences[0].UID, "unrelated deployment ownerRef must not be modified")
}

func TestReconcileWithoutDeprecatedCRDs(t *testing.T) {
	scheme := runtime.NewScheme()
	scheme.AddKnownTypes(
		temporaliov1alpha1.GroupVersion,
		&temporaliov1alpha1.WorkerDeployment{},
		&temporaliov1alpha1.WorkerDeploymentList{},
	)
	metav1.AddToGroupVersion(scheme, temporaliov1alpha1.GroupVersion)

	now := metav1.Now()
	wd := &temporaliov1alpha1.WorkerDeployment{
		ObjectMeta: metav1.ObjectMeta{
			Name:              "worker",
			Namespace:         "default",
			DeletionTimestamp: &now,
			Finalizers:        []string{"test"},
		},
	}
	fakeClient := fake.NewClientBuilder().
		WithScheme(scheme).
		WithObjects(wd).
		Build()
	r := &WorkerDeploymentReconciler{
		Client: fakeClient,
		Scheme: scheme,
	}
	r.Config.DisableDeprecatedTWD = true

	_, err := r.Reconcile(context.Background(), ctrl.Request{
		NamespacedName: types.NamespacedName{Name: wd.Name, Namespace: wd.Namespace},
	})
	require.NoError(t, err)
}

//go:build integration

package integration

import (
	"context"
	"sync"
	"testing"
	"time"

	temporaliov1alpha1 "github.com/temporalio/temporal-worker-controller/api/v1alpha1"
	"github.com/temporalio/temporal-worker-controller/internal/k8s"
	"github.com/temporalio/temporal-worker-controller/internal/testhelpers"
	"go.temporal.io/sdk/worker"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/util/retry"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

func waitTimeout(wg *sync.WaitGroup, timeout time.Duration) bool {
	c := make(chan struct{})
	go func() {
		defer close(c)
		wg.Wait()
	}()
	select {
	case <-c:
		return false // completed normally
	case <-time.After(timeout):
		return true // timed out
	}
}

// startWorker starts a single worker for the given deployment and returns a stop function.
// The caller is responsible for calling the stop function when done.
func startWorker(t *testing.T, ctx context.Context, k8sClient client.Client, deploymentName, namespace string) func() {
	var deployment appsv1.Deployment
	if err := k8sClient.Get(ctx, types.NamespacedName{
		Name:      deploymentName,
		Namespace: namespace,
	}, &deployment); err != nil {
		t.Fatalf("failed to get deployment: %v", err)
		return func() {}
	}

	startedCh := make(chan struct{})
	var stop func()
	workerCallback := func(stopFunc func(), err error) {
		if err != nil {
			t.Errorf("failed to start worker: %v", err)
		} else {
			startedCh <- struct{}{}
			stop = stopFunc
		}
	}

	testhelpers.RunHelloWorldWorker(ctx, deployment.Spec.Template, workerCallback)
	// wait for worker to start
	<-startedCh

	return func() {
		if stop != nil {
			stop()
		}
	}
}

func applyDeployment(t *testing.T, ctx context.Context, k8sClient client.Client, deploymentName, namespace string) []func() {
	var deployment appsv1.Deployment
	if err := k8sClient.Get(ctx, types.NamespacedName{
		Name:      deploymentName,
		Namespace: namespace,
	}, &deployment); err != nil {
		t.Fatalf("failed to get deployment: %v", err)
	}

	var wg sync.WaitGroup
	stopFuncs := make([]func(), *(deployment.Spec.Replicas))
	workerErrors := make([]error, *(deployment.Spec.Replicas))
	workerCallback := func(i int32) func(func(), error) {
		return func(stopFunc func(), err error) {
			if err == nil {
				stopFuncs[i] = stopFunc
				wg.Done()
			} else {
				workerErrors[i] = err
			}
		}
	}

	for i := int32(0); i < *(deployment.Spec.Replicas); i++ {
		wg.Add(1)
		go testhelpers.RunHelloWorldWorker(ctx, deployment.Spec.Template, workerCallback(i))
	}

	// wait 30s for all expected workers to be healthy (under suite load startup can be slower)
	timedOut := waitTimeout(&wg, 30*time.Second)

	if timedOut {
		t.Fatalf("could not start workers, errors were: %+v", workerErrors)
	} else {
		setHealthyDeploymentStatus(t, ctx, k8sClient, deployment)
	}

	return stopFuncs
}

// Set deployment status to `DeploymentAvailable` to simulate a healthy deployment.
// This is necessary because envtest doesn't actually start pods.
// Uses retry-on-conflict because the controller may update the Deployment (e.g. rolling
// update) between our Get and Status().Update(), bumping the resourceVersion.
func setHealthyDeploymentStatus(t *testing.T, ctx context.Context, k8sClient client.Client, deployment appsv1.Deployment) {
	t.Helper()
	err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		var fresh appsv1.Deployment
		if err := k8sClient.Get(ctx, types.NamespacedName{Name: deployment.Name, Namespace: deployment.Namespace}, &fresh); err != nil {
			return err
		}
		now := metav1.Now()
		fresh.Status = appsv1.DeploymentStatus{
			Replicas:            *fresh.Spec.Replicas,
			UpdatedReplicas:     *fresh.Spec.Replicas,
			ReadyReplicas:       *fresh.Spec.Replicas,
			AvailableReplicas:   *fresh.Spec.Replicas,
			UnavailableReplicas: 0,
			Conditions: []appsv1.DeploymentCondition{
				{
					Type:               appsv1.DeploymentAvailable,
					Status:             corev1.ConditionTrue,
					LastUpdateTime:     now,
					LastTransitionTime: now,
					Reason:             "MinimumReplicasAvailable",
					Message:            "Deployment has minimum availability.",
				},
				{
					Type:               appsv1.DeploymentProgressing,
					Status:             corev1.ConditionTrue,
					LastUpdateTime:     now,
					LastTransitionTime: now,
					Reason:             "NewReplicaSetAvailable",
					Message:            "ReplicaSet is available.",
				},
			},
		}
		return k8sClient.Status().Update(ctx, &fresh)
	})
	if err != nil {
		t.Fatalf("failed to update deployment status after retries: %v", err)
	}
}

// scaleDeploymentToZero scales a versioned Deployment to zero replicas and reflects that
// in its status (envtest has no kubelet to do so). A drained version only becomes
// EligibleForDeletion once its Deployment reports zero replicas (see state_mapper.go), so
// this is how a test drives a drained version to the point where the controller will prune
// its Temporal server-side version record on sunset.
func scaleDeploymentToZero(t *testing.T, ctx context.Context, k8sClient client.Client, name, namespace string) {
	t.Helper()
	zero := int32(0)
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		var dep appsv1.Deployment
		if err := k8sClient.Get(ctx, types.NamespacedName{Name: name, Namespace: namespace}, &dep); err != nil {
			return err
		}
		dep.Spec.Replicas = &zero
		return k8sClient.Update(ctx, &dep)
	}); err != nil {
		t.Fatalf("failed to scale deployment %s to zero: %v", name, err)
	}
	if err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		var dep appsv1.Deployment
		if err := k8sClient.Get(ctx, types.NamespacedName{Name: name, Namespace: namespace}, &dep); err != nil {
			return err
		}
		dep.Status.Replicas = 0
		dep.Status.ReadyReplicas = 0
		dep.Status.AvailableReplicas = 0
		dep.Status.UpdatedReplicas = 0
		dep.Status.ObservedGeneration = dep.Generation
		return k8sClient.Status().Update(ctx, &dep)
	}); err != nil {
		t.Fatalf("failed to zero status of deployment %s: %v", name, err)
	}
}

// Uses input.Status + existingDeploymentReplicas to create (and maybe kill) pollers for deprecated versions in temporal
// also gets routing config of the deployment into the starting state before running the test.
// Does not set Status.VersionConflictToken, since that is only set internally by the server.
// Returns stop functions for all started workers that the caller must defer to ensure cleanup.
func makePreliminaryStatusTrue(
	ctx context.Context,
	t *testing.T,
	env testhelpers.TestEnv,
	twd *temporaliov1alpha1.WorkerDeployment,
	previouslyCurrentImages []string,
) {
	t.Logf("Creating starting test env based on input.Status")

	// Make a separate list of deferred functions, because calling defer in a for loop is not allowed.
	loopDefers := make([]func(), 0)
	defer handleStopFuncs(loopDefers)
	for _, dv := range twd.Status.DeprecatedVersions {
		t.Logf("Setting up deprecated version %v with status %v", dv.BuildID, dv.Status)
		workerStopFuncs := createStatus(ctx, t, env, twd, dv.BaseWorkerDeploymentVersion, nil)
		loopDefers = append(loopDefers, func() { handleStopFuncs(workerStopFuncs) })
	}

	// Register versions that were previously current so they have LastCurrentTime set in Temporal
	workerDeploymentName := k8s.ComputeWorkerDeploymentName(twd)
	for _, image := range previouslyCurrentImages {
		buildID := testhelpers.MakeBuildID(twd.Name, image, "", nil)
		t.Logf("Setting LastCurrentTime for previously-current version %q (buildID %q)", image, buildID)
		stopFunc, err := testhelpers.StartVersionedWorker(ctx, workerDeploymentName, buildID, twd.Name,
			env.Ts.GetFrontendHostPort(), env.Ts.GetDefaultNamespace())
		if err != nil {
			t.Errorf("failed to start worker for previously-current build %q: %v", buildID, err)
			continue
		}
		waitForVersionRegistrationInDeployment(t, ctx, env.Ts, &worker.WorkerDeploymentVersion{
			DeploymentName: workerDeploymentName,
			BuildID:        buildID,
		})
		setCurrentVersion(t, ctx, env.Ts, workerDeploymentName, buildID)
		loopDefers = append(loopDefers, stopFunc)
	}

	if tv := twd.Status.TargetVersion; tv.BuildID != "" {
		t.Logf("Setting up target version %v with status %v", tv.BuildID, tv.Status)
		var rampPercentage *float32
		if tv.RampPercentage != nil {
			percentage := *tv.RampPercentage
			rampPercentage = &percentage
		}
		workerStopFuncs := createStatus(ctx, t, env, twd, tv.BaseWorkerDeploymentVersion, rampPercentage)
		defer handleStopFuncs(workerStopFuncs)
	}
}

func handleStopFuncs(funcs []func()) {
	for _, f := range funcs {
		if f != nil {
			f()
		}
	}
}

// creates k8s deployment, pollers, and routing config state as needed.
func createStatus(
	ctx context.Context,
	t *testing.T,
	env testhelpers.TestEnv,
	newTWD *temporaliov1alpha1.WorkerDeployment,
	prevVersion temporaliov1alpha1.BaseWorkerDeploymentVersion,
	rampPercentage *float32,
) (workerStopFuncs []func()) {
	if prevVersion.Deployment != nil && prevVersion.Deployment.FieldPath == "create" {
		workerDeploymentName := k8s.ComputeWorkerDeploymentName(newTWD)
		v := &worker.WorkerDeploymentVersion{
			DeploymentName: workerDeploymentName,
			BuildID:        prevVersion.BuildID,
		}
		prevTWD := recreateTWD(newTWD, env.ExistingDeploymentImages[v.BuildID], env.ExistingDeploymentReplicas[v.BuildID])
		createWorkerDeployment(ctx, t, env, prevTWD, v.BuildID)
		expectedDeploymentName := k8s.ComputeVersionedDeploymentName(prevTWD.Name, k8s.ComputeBuildID(prevTWD))
		waitForExpectedTargetDeployment(t, prevTWD, env, 30*time.Second)
		workerStopFuncs = applyDeployment(t, ctx, env.K8sClient, expectedDeploymentName, prevTWD.Namespace)

		switch prevVersion.Status {
		case temporaliov1alpha1.VersionStatusNotRegistered:
			// no-op
		case temporaliov1alpha1.VersionStatusInactive:
			waitForVersionRegistrationInDeployment(t, ctx, env.Ts, v)
		case temporaliov1alpha1.VersionStatusRamping:
			setRampingVersion(t, ctx, env.Ts, v.DeploymentName, v.BuildID, *rampPercentage) // rampPercentage won't be nil if the version is ramping
		case temporaliov1alpha1.VersionStatusCurrent:
			setCurrentVersion(t, ctx, env.Ts, v.DeploymentName, v.BuildID)
		case temporaliov1alpha1.VersionStatusDraining:
			setRampingVersion(t, ctx, env.Ts, v.DeploymentName, v.BuildID, 1)
			// TODO(carlydf): start a workflow on v that does not complete -> will never drain
			setRampingVersion(t, ctx, env.Ts, v.DeploymentName, "", 0)
		case temporaliov1alpha1.VersionStatusDrained:
			if env.ExistingDeploymentReplicas[v.BuildID] == 0 {
				// Keep the temporary worker alive until setCurrentVersion completes.
				// Stopping it before the call risks the Worker Deployment entry being
				// cleaned up (under short PollerHistoryTTL) before registration is confirmed.
				stopTemporaryWorker := startWorker(t, ctx, env.K8sClient, expectedDeploymentName, prevTWD.Namespace)
				setCurrentVersion(t, ctx, env.Ts, v.DeploymentName, v.BuildID)
				stopTemporaryWorker()
			} else {
				setCurrentVersion(t, ctx, env.Ts, v.DeploymentName, v.BuildID)
			}
			setCurrentVersion(t, ctx, env.Ts, v.DeploymentName, "")
		}
	}

	return workerStopFuncs
}

// recreateTWD returns a copy of the given TWD, but replaces the build-id-generating image name with the given one,
// and the Spec.Replicas with the given replica count.
// Panics if the twd spec is nil, or if it has no containers, but that should never be true for these integration tests.
func recreateTWD(twd *temporaliov1alpha1.WorkerDeployment, imageName string, replicas int32) *temporaliov1alpha1.WorkerDeployment {
	ret := twd.DeepCopy()
	ret.Spec.Deployment.Template.Spec.Containers[0].Image = imageName
	ret.Spec.Deployment.Replicas = &replicas
	return ret
}

func createWorkerDeployment(
	ctx context.Context,
	t *testing.T,
	env testhelpers.TestEnv,
	twd *temporaliov1alpha1.WorkerDeployment,
	buildId string,
) {
	dep, err := k8s.NewDeploymentWithControllerRef(twd, buildId, env.Connection.Spec, env.Mgr.GetScheme())
	if err != nil {
		t.Fatalf("error creating Deployment spec: %v", err.Error())
	}

	t.Logf("Creating Deployment %s in namespace %s", dep.Name, dep.Namespace)

	if err := env.K8sClient.Create(ctx, dep); err != nil {
		t.Fatalf("failed to create Deployment: %v", err)
	}
}
